// Generated by scripts/optimize-assets.mjs from Unsplash-licensed photo sources.
export type OptimizedImage = {
  id: string;
  alt: string;
  label: string;
  src: string;
  srcSet: string;
  largeSrc: string;
  width: number;
  height: number;
};

const unsplashImage = (photoId: string) => {
  const url = (width: number) =>
    `https://images.unsplash.com/${photoId}?auto=format&fit=crop&crop=entropy&w=${width}&h=${Math.round(width * 4 / 3)}&q=82`;
  return {
    src: url(840),
    srcSet: [420, 840, 1280].map((width) => `${url(width)} ${width}w`).join(", "),
    largeSrc: url(1800),
  };
};

